MARK = '@ ---- Orange Islands trainers (orange_route_trainers.py) ----'
trainers = [f['trainer'] for f in FINAL]

p = 'include/constants/opponents.h'; t = rd(p)
if trainers[0]['const'] not in t:
    n = int(re.search(r'#define NUM_TRAINERS\s+(\d+)', t).group(1))
    last = list(re.finditer(r'#define TRAINER_JOHTO_\w+\s+\d+\n', t))[-1]
    t = t[:last.end()] + '\n// Orange Islands route trainers\n' + ''.join('#define %-40s %d\n' % (tr['const'], n + i) for i, tr in enumerate(trainers)) + t[last.end():]
    t = re.sub(r'#define NUM_TRAINERS\s+\d+', '#define NUM_TRAINERS                             %d' % (n + len(trainers)), t)
    wr(p, t)

p = 'src/data/trainers.h'; t = rd(p)
if '[%s]' % trainers[0]['const'] not in t:
    ent = ''
    for tr in trainers:
        music = 'TRAINER_ENCOUNTER_MUSIC_' + tr['music'] + (' | F_TRAINER_FEMALE' if tr['female'] else '')
        ent += ('    [%s] = {\n        .trainerClass = TRAINER_CLASS_%s,\n        .encounterMusic_gender = %s,\n'
                '        .trainerPic = TRAINER_PIC_%s,\n        .trainerName = _("%s"),\n        .items = {},\n'
                '        .doubleBattle = FALSE,\n        .aiFlags = %s,\n        .party = POOL_PARTY(%s, %d, %d, %d, %d),\n    },\n') % (
                tr['const'], tr['class'], music, tr['pic'], tr['name'], tr['ai'], tr['pool'], tr['min'], tr['max'], tr['level'], tr['range'])
    last = list(re.finditer(r'    \[TRAINER_JOHTO_\w+\] = \{', t))[-1]
    j = t.index('    },\n', last.start()) + len('    },\n')
    t = t[:j] + ent + t[j:]
    wr(p, t)

bymap = {}
for f in FINAL: bymap.setdefault(f['map'], []).append(f)
for mp, fs in bymap.items():
    p = 'data/maps/%s/map.json' % mp
    mj = json.loads(rd(p))
    have = {o.get('script') for o in mj.get('object_events', [])}
    for f in fs:
        if f['script'] in have: continue
        mj.setdefault('object_events', []).append({
            'type': 'object', 'graphics_id': f['gfx'], 'x': f['x'], 'y': f['y'], 'elevation': f['elev'],
            'movement_type': f['move'], 'movement_range_x': 1, 'movement_range_y': 1,
            'trainer_type': 'TRAINER_TYPE_NORMAL', 'trainer_sight_or_berry_tree_id': str(f['sight']),
            'script': f['script'], 'flag': '0'})
    wr(p, json.dumps(mj, indent=2, ensure_ascii=False) + '\n')
    p = 'data/maps/%s/scripts.inc' % mp
    t = rd(p)
    if MARK in t: continue
    s = '\n' + MARK + '\n'; texts = ''
    for f in fs:
        tr = f['trainer']; lb = f['script']; base = lb.replace('_EventScript_', '_Text_')
        s += '%s::\n\ttrainerbattle_single %s, %sIntro, %sDefeat\n\tmsgbox %sPostBattle, MSGBOX_AUTOCLOSE\n\tend\n\n' % (lb, tr['const'], base, base, base)
        for key, part in (('seen', 'Intro'), ('beaten', 'Defeat'), ('after', 'PostBattle')):
            texts += '%s%s::\n' % (base, part) + ''.join('\t.string "%s"\n' % l for l in f[key]) + '\n'
    wr(p, t.rstrip('\n') + '\n' + s + texts)
print('orange route trainers ok: %d trainers' % len(trainers))
